      svgElement: svgElement,
      laidOutTree: laidOutTree,
      palette: palette,
      theme: theme,
      animate: shouldAnimate,
      signature: signature,
      viewBox: viewBox,
      previousBox: svgElement._blackoutBox || viewBox,
      previousPositions: svgElement._blackoutPositions || {},
      seenBefore: svgElement._blackoutSeen || {},
